function toTitleCase(str) {
  if (!str) return '';
  return String(str)
    .toLowerCase()
    .replace(/(?:^|\s|-|\/)[a-z]/g, function(c) {
      return c.toUpperCase();
    })
    .replace(/\bPolri\b/gi, 'Polri')
    .replace(/\bPolda\b/gi, 'Polda')
    .replace(/\bPolrestabes\b/gi, 'Restabes')
    .replace(/\bPolresta\b/gi, 'Resta')
    .replace(/\bPolres\b/gi, 'Res')
    .replace(/\bPolsekta\b/gi, 'Sekta')
    .replace(/\bPolsek\b/gi, 'Sek')
    .replace(/\bDitreskrimum\b/gi, 'Ditreskrimum')
    .replace(/\bDitreskrimsus\b/gi, 'Ditreskrimsus')
    .replace(/\bDitresnarkoba\b/gi, 'Ditresnarkoba')
    .replace(/\bSatreskrim\b/gi, 'Satreskrim')
    .replace(/\bSatresnarkoba\b/gi, 'Satresnarkoba')
    .replace(/\bBareskrim\b/gi, 'Bareskrim')
    .replace(/\bRobinopsnal\b/gi, 'Robinopsnal')
    .replace(/\bPapua\s+Barat\s+Daya\b/gi, 'Pabardaya')
    .replace(/\bPabardaya\b/gi, 'Pabardaya')
    .replace(/\bPabd\b/gi, 'Pabardaya')
    .replace(/\bPapua\s+Tengah\b/gi, 'Papteng')
    .replace(/\bPapteng\b/gi, 'Papteng')
    .replace(/\bPateng\b/gi, 'Papteng')
    .replace(/\bKawasan\s+Pelabuhan\b/gi, 'K.P.')
    .replace(/\bKawasan\s+Bandara\b/gi, 'K.B.')
    .replace(/\bK\.?\s*p\.?\s+/gi, 'K.P. ')
    .replace(/\bK\.?\s*b\.?\s+/gi, 'K.B. ')
    .replace(/\bTanjung\b/gi, 'Tj.')
    .replace(/\bTj\.?\s+/gi, 'Tj. ')
    .replace(/\bKepulauan\b/gi, 'Kep.')
    .replace(/\bKep\.?\s+/gi, 'Kep. ')
    .replace(/\bPulau\b/gi, 'P.')
    .replace(/\bP\.?\s+/gi, 'P. ');
}
